import{_ as r,a0 as l,w as a,s,I as u,x as t,a1 as i,A as o,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"如何在Linux Mint 16中正確安裝Ubuntu One | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux Mint 16中正確安裝Ubuntu One | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux Mint 16中正確安裝Ubuntu One | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux Mint 16中正確安裝Ubuntu One | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/How To Properly Install Ubuntu One In Linux Mint 16","title":"如何在Linux Mint 16中正確安裝Ubuntu One","tag":"201402","desc":""},"relativePath":"201402/How To Properly Install Ubuntu One In Linux Mint 16.md","filePath":"[post].md"}'),d={name:"201402/How To Properly Install Ubuntu One In Linux Mint 16.md"};function b(x,n,m,f,L,O){const e=l("Link");return a(),s("div",null,[n[16]||(n[16]=u("h1",{id:"如何在linux-mint-16中正確安裝ubuntu-one",tabindex:"-1"},[t("如何在Linux Mint 16中正確安裝Ubuntu One "),u("a",{class:"header-anchor",href:"#如何在linux-mint-16中正確安裝ubuntu-one","aria-label":"Permalink to “如何在Linux Mint 16中正確安裝Ubuntu One”"},"​")],-1)),n[17]||(n[17]=u("p",null,[u("img",{src:"http://itsfoss.com/wp-content/uploads/2014/01/Ubuntu-One-Linux-Mint.jpg",alt:""})],-1)),u("p",null,[n[1]||(n[1]=t("由於",-1)),i(e,{href:"http://www.linuxmint.com/"},{default:o(()=>[...n[0]||(n[0]=[t("Linux Mint",-1)])]),_:1}),n[2]||(n[2]=t("是基於 Ubuntu 的，所以我認為 Ubuntu One 應該是預裝程序之一。不過我錯了。我自行從 Software Manager 安裝了 Ubuntu One，令我驚訝的是，它居然無法正常運行。在這篇教程中我們會告訴你",-1)),n[3]||(n[3]=u("strong",null,"如何在 Linux Mint 16中安裝 Ubuntu One",-1)),n[4]||(n[4]=t(" 以及如何正常運行它。",-1))]),n[18]||(n[18]=p(`<h3 id="在linux-mint-16-中安裝-ubuntu-one" tabindex="-1">在Linux Mint 16 中安裝 Ubuntu One: <a class="header-anchor" href="#在linux-mint-16-中安裝-ubuntu-one" aria-label="Permalink to “在Linux Mint 16 中安裝 Ubuntu One:”">​</a></h3><p>當你通過 Software Manager 安裝 Ubuntu One 客户端以後，你準備打開並配置它時，你甚至都無法在菜單搜索裏面找到它。就像是完全沒有安裝過一樣。但你查看 Software Manager，又顯示它已經安裝完成了。問題到底出在哪了？</p><p>問題的關鍵是 <strong>Ubuntu One installer</strong> 需要 <strong>ubuntuone-control-panel-qt</strong> 包。這個包沒有安裝，你的 Ubuntu One 的安裝過程就無法運行。要解決這個問題，打開終端 (Ctrl+Alt+T)並運行下面的命令：</p><pre><code>sudo apt-get install ubuntuone-control-panel-qt
</code></pre><p>現在你在菜單裏面搜索，你會發現 Ubuntu One 已經存在了。現在你可以配置賬户，選擇哪些同步和哪些不同步。現在你可能覺得你已經解決了所有的問題，這時你會發現 <strong>Ubuntu One 指示器並沒出現在面板上</strong>。</p><h3 id="在-linux-mint-16-中安裝-ubuntu-one-indicator" tabindex="-1">在 Linux Mint 16 中安裝 Ubuntu One indicator: <a class="header-anchor" href="#在-linux-mint-16-中安裝-ubuntu-one-indicator" aria-label="Permalink to “在 Linux Mint 16 中安裝 Ubuntu One indicator:”">​</a></h3><p>你可以通過添加以下的 PPA 在 Linux Mint 中獲取 Ubuntu One indicator 程序：</p><pre><code>sudo add-apt-repository ppa:rye/ubuntuone-extras
sudo apt-get update 
sudo apt-get install indicator-ubuntuone
</code></pre><p>註銷並重新登錄後，你會看到這個指示器已經出現在面板中。與此同時，你的 Ubuntu One 也全部安裝完成了。我希望這篇 <strong>在 Linux Mint 中安裝 Ubuntu One</strong> 會對你有所幫助。歡迎提出問題和建議。</p><hr>`,10)),u("p",null,[n[6]||(n[6]=t("via: ",-1)),i(e,{href:"http://itsfoss.com/ubuntu-one-linux-mint-16/"},{default:o(()=>[...n[5]||(n[5]=[t("http://itsfoss.com/ubuntu-one-linux-mint-16/",-1)])]),_:1})]),u("p",null,[n[9]||(n[9]=t("譯者：",-1)),i(e,{href:"https://github.com/yechunxiao19"},{default:o(()=>[...n[7]||(n[7]=[t("烏龍茶",-1)])]),_:1}),n[10]||(n[10]=t(" 校對：",-1)),i(e,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...n[8]||(n[8]=[t("Caroline",-1)])]),_:1})]),u("p",null,[n[13]||(n[13]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[11]||(n[11]=[t("LCTT",-1)])]),_:1}),n[14]||(n[14]=t(" 原創翻譯，",-1)),i(e,{href:"http://linux.cn/"},{default:o(()=>[...n[12]||(n[12]=[t("Linux中國",-1)])]),_:1}),n[15]||(n[15]=t(" 榮譽推出",-1))])])}const g=r(d,[["render",b]]);export{M as __pageData,g as default};
